pug:
table.iq-text-title--iq-text-title(role="presentation" width="100%")
    tr
        td(style="text-align:{{ align }}")
            p.iq-text-title--iq-middle-title(style="color:{{ title_color }};padding:{{ title_padding }}") {{ title }}
            p.iq-text-title--iq-body-text(style="color:{{ body_color }};padding:{{ body_padding }}") {{ body }}

styl:
.iq-text-title--iq-text-title{width:100%}
.iq-text-title--iq-middle-title{color:{{ title_color }};font-family:Helvetica,Arial,sans-serif!important;font-size:32px;font-weight:700;line-height:42px;margin:0;padding:{{ title_padding }};vertical-align:middle}
@media screen and (max-width:600px){.iq-text-title--iq-middle-title{font-size:28px!important;line-height:34px!important}}
.iq-text-title--iq-body-text{color:{{ body_color }};font-family:Helvetica,Arial,sans-serif!important;font-size:18px;font-weight:400;letter-spacing:0;line-height:26px;margin:0;padding:{{ body_padding }}}
